const { remote } = require('webdriverio');
const fs = require('fs');
const T = '/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode';

(async () => {
  const browser = await remote({
    port: 4723,
    logLevel: 'error',
    capabilities: {
      platformName: 'iOS',
      'appium:automationName': 'XCUITest',
      'appium:udid': 'FC1F4381-BE86-4AA5-8FC7-4558E002867E',
      'appium:bundleId': 'im.vector.app',
      'appium:noReset': true,
      'appium:autoLaunch': false,
      'appium:autoAcceptAlerts': true,
      'appium:wdaLaunchTimeout': 240000,
    },
