  const log = (m) => console.log('STEP', m);

  log('tapping Team Standup cell');
  await browser.execute('mobile: tap', { x: 196, y: 534 });
  await browser.pause(3000);

  const gotIt = await browser.$('~Got it');
  if (await gotIt.isExisting()) {
    log('dismissing popup');
    await gotIt.click();
    await browser.pause(1500);
  }

  const composer = await browser.$('~GrowingTextView');
  await composer.waitForExist({ timeout: 15000 });
  log('composer found, clicking');
  await composer.click();
  await browser.pause(1000);
  await composer.setValue('good morning');
  await browser.pause(1000);
  let val = await composer.getValue();
  log('composer value: ' + JSON.stringify(val));
  if (!val || !val.includes('good morning')) {
    log('fallback keys');
    await browser.keys('good morning');
    await browser.pause(1000);
  }

  const send = await browser.$('~SendButton');
  await browser.waitUntil(async () => await send.isEnabled(), { timeout: 8000 });
  log('clicking send');
  await send.click();
  await browser.pause(3000);

  const src = await browser.getPageSource();
  fs.writeFileSync(T + '/source4.xml', src);
  log('done');
  await browser.deleteSession();
})().catch((e) => { console.error('ERR', e.message); process.exit(1); });

const { remote } = require('webdriverio');
const fs = require('fs');
const { execSync } = require('child_process');
const T = '/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode';
const UDID = 'FC1F4381-BE86-4AA5-8FC7-4558E002867E';

function ensureApp() {
  try {
    const out = execSync(`xcrun simctl launch ${UDID} im.vector.app 2>&1`).toString();
    console.log('launch:', out.trim());
  } catch (e) { console.log('launch err', e.message); }
}

async function connect() {
  return await remote({
    port: 4723,
    logLevel: 'error',
    capabilities: {
      platformName: 'iOS',
      'appium:automationName': 'XCUITest',
      'appium:udid': UDID,
      'appium:bundleId': 'im.vector.app',
      'appium:noReset': true,
      'appium:autoLaunch': false,
      'appium:autoAcceptAlerts': true,
      'appium:wdaLaunchTimeout': 240000,
    },
  });
}

(async () => {
  for (let attempt = 1; attempt <= 6; attempt++) {
    console.log('ATTEMPT', attempt);
    let browser = null;
    try {
      ensureApp();
      await new Promise(r => setTimeout(r, 5000));
      browser = await connect();
      await browser.pause(1000);

      const roomTitle = await browser.$('//XCUIElementTypeStaticText[@name="TitleLabel" and @visible="true" and @value="Team Standup"]');
      const composer0 = await browser.$('~GrowingTextView');
      const inRoom = await composer0.isExisting();
      if (!inRoom && await roomTitle.isExisting()) {
        const loc = await roomTitle.getLocation();
        const sz = await roomTitle.getSize();
        console.log('tapping room cell at', loc.x + sz.width / 2, loc.y + sz.height / 2);
        await browser.execute('mobile: tap', { x: loc.x + sz.width / 2, y: loc.y + sz.height / 2 });
        await browser.pause(2500);
      } else if (!inRoom) {
        console.log('neither chat list nor room detected; dumping source');
        fs.writeFileSync(T + `/debug_attempt${attempt}.xml`, await browser.getPageSource());
        throw new Error('unknown screen');
      }

      const gotIt = await browser.$('~Got it');
      if (await gotIt.isExisting()) {
        console.log('dismissing popup');
        await gotIt.click();
        await browser.pause(1000);
      }

      const composer = await browser.$('~GrowingTextView');
      await composer.waitForExist({ timeout: 10000 });
      await composer.click();
      await browser.pause(600);
      await composer.setValue('good morning');
      await browser.pause(600);
      let val = String(await composer.getValue());
      if (!val.includes('good morning')) {
        console.log('fallback typing');
        await browser.keys('good morning');
        await browser.pause(600);
      }

      const send = await browser.$('~SendButton');
      await browser.waitUntil(async () => await send.isEnabled(), { timeout: 8000 });
      console.log('clicking send');
      await send.click();
      await browser.pause(2500);

      const src = await browser.getPageSource();
      fs.writeFileSync(T + '/source_final.xml', src);
      if (src.includes('good morning')) {
        console.log('SUCCESS: message present in room');
        await browser.deleteSession();
        process.exit(0);
      }
      throw new Error('message not found after send');
    } catch (e) {
      console.log('attempt failed:', e.message);
      if (browser) { try { await browser.deleteSession(); } catch (_) {} }
      await new Promise(r => setTimeout(r, 2000));
    }
  }
  console.log('ALL ATTEMPTS FAILED');
  process.exit(1);
})();
